package main

import (
	"fmt"
	"os"
)

func main() {
	const key = "INTERVIEW_EXPLAINER_LOOKUP_DEMO"
	old, existed := os.LookupEnv(key)
	defer func() {
		if existed {
			_ = os.Setenv(key, old)
		} else {
			_ = os.Unsetenv(key)
		}
	}()

	if err := os.Setenv(key, ""); err != nil {
		panic(err)
	}
	value, found := os.LookupEnv(key)
	fmt.Printf("present: Getenv=%q LookupEnv=%q,%t\n", os.Getenv(key), value, found)

	if err := os.Unsetenv(key); err != nil {
		panic(err)
	}
	value, found = os.LookupEnv(key)
	fmt.Printf("missing: Getenv=%q LookupEnv=%q,%t\n", os.Getenv(key), value, found)
}
