package main

import (
	"fmt"
	"strconv"
)

type Config struct{ Port int }
type Lookup func(string) (string, bool)

func loadConfig(lookup Lookup) (Config, error) {
	raw, found := lookup("APP_PORT")
	if !found || raw == "" {
		return Config{}, fmt.Errorf("APP_PORT is required")
	}
	port, err := strconv.Atoi(raw)
	if err != nil || port < 1 || port > 65535 {
		return Config{}, fmt.Errorf("APP_PORT must be an integer from 1 to 65535")
	}
	return Config{Port: port}, nil
}

func main() {
	values := map[string]string{"APP_PORT": "8080"}
	config, err := loadConfig(func(key string) (string, bool) {
		value, found := values[key]
		return value, found
	})
	if err != nil {
		panic(err)
	}
	fmt.Printf("%+v\n", config)
}
