package main

import (
	"fmt"
	"sync"
)

func mode(lookup func(string) (string, bool)) string {
	value, found := lookup("APP_MODE")
	if !found {
		return "default"
	}
	return value
}

func main() {
	var wg sync.WaitGroup
	results := make(chan string, 2)
	for _, value := range []string{"dev", "prod"} {
		value := value
		wg.Add(1)
		go func() {
			defer wg.Done()
			results <- mode(func(string) (string, bool) { return value, true })
		}()
	}
	wg.Wait()
	close(results)
	seen := map[string]bool{}
	for result := range results {
		seen[result] = true
	}
	fmt.Println(seen["dev"], seen["prod"])
}
